'use client';
import React,{useState,useEffect,useRef} from 'react';
import {ArrowUpRight,ArrowRight,ArrowLeft,Check,Plus,X,MapPin,CalendarDays,Clock3,Users,Wallet,ShieldCheck,Sparkles,BookOpen,CheckCircle2,ChevronLeft,ChevronRight,Search,SlidersHorizontal,FileText,Upload,MessageCircle,Send,Camera,Activity,Leaf,AlertCircle,Video,Download,ExternalLink,Cat} from 'lucide-react';
import {services,extras,money,statuses} from '../lib/domain';
import {cityById,cities} from '../lib/marketplace-policy';
